import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.T_JR4O6h.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/guide/introduction.html"}],["meta",{"property":"og:title","content":"Introduction | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/guide/introduction.html"}],["meta",{"name":"twitter:title","content":"Introduction | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),o={name:"guide/introduction.md"};function i(d,e,c,l,s,m){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Kiln is a WebGPU-native, out-of-core volume renderer for large volumetric datasets. It streams multi-gigabyte volumes over HTTP into a bounded GPU residency/atlas cache, resolving them through virtual-texture indirection.</p><p>Kiln streams <a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/data/ome-zarr.html">OME-Zarr</a> (NGFF v0.4/v0.5) datasets directly — single-channel and multichannel, up to 4 channels — as well as a compressed <a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/data/sharded-binary.html">sharded binary format</a>. Input can be <code>uint8</code>, <code>uint16</code>, or <code>float32</code>; <code>uint16</code> and <code>float32</code> are converted to <code>r16float</code> for GPU storage.</p><h2 id="where-to-next" tabindex="-1">Where to next <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to next&quot;">​</a></h2><ul><li><strong><a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/guide/quick-start.html">Quick start</a></strong> — get a viewer rendering a streamed volume in a few lines.</li><li><strong><a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/guide/loading-data.html">Loading data</a></strong> — remote OME-Zarr, local files, and multichannel datasets.</li><li><strong><a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/guide/url-parameters.html">URL parameters</a></strong> — share and bookmark specific views.</li><li><strong><a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/gallery.html">Gallery</a></strong> — live example datasets, each opening directly in the viewer.</li><li><strong><a href="/preview/dependabot-npm-and-yarn-npm-and-yarn-3ac77625be/architecture/overview.html">Architecture</a></strong> — how the virtual texturing and streaming systems work.</li></ul>',5)])])}const h=t(o,[["render",i]]);export{u as __pageData,h as default};
